import { useLocation, useNavigate } from "react-router-dom";
import { useEffect } from "react";

function Dashboard() {
    const location = useLocation();
    const navigate = useNavigate();

    // Extract data passed from Login
    const fullData = location.state?.data;
    const responseData = fullData?.Response;

    useEffect(() => {
        if (!responseData) {
            navigate("/login");
        }
    }, [responseData, navigate]);

    if (!responseData) return <p>Redirecting to login...</p>;

    return (
        <div style={{ padding: "20px", fontFamily: "Arial" }}>
            <h1>Welcome to Dashboard</h1>

            <div style={{
                backgroundColor: "#f9f9f9",
                padding: "20px",
                borderRadius: "10px",
                boxShadow: "0 0 5px rgba(0,0,0,0.1)"
            }}>
                <h2>Status: {responseData.Status}</h2>
                <h3>Message: {responseData.Message}</h3>

                {responseData.UserInfo && (
                    <>
                        <h3>User Info:</h3>
                        <ul>
                            {Object.entries(responseData.UserInfo).map(([key, value]) => (
                                <li key={key}><strong>{key}</strong>: {value}</li>
                            ))}
                        </ul>
                    </>
                )}
            </div>
        </div>
    );
}

export default Dashboard;
